// Resolve Store Config from Gravity Environment
// Supports: Auto World Store (division 30), Big Country Toys (division 40)
// Fixed NetSuite header values: subsidiary 3, currency 1

// NOTE: In production, the storeName should come from an environment variable or workflow input.
// For now, defaulting to "Big Country Toys" to match the connected Shopify account.
const storeName = input.workflowArguments?.environment || "Big Country Toys";
const emailsRecipients = "bruno@mindcloud.co, AMiller@lionel.com, jjones@lionel.com"

const storeConfigs = {
  "Auto World": {
    storeName: "Auto World Store",
    division: "3",
    subsidiary: "3",
    currency: "1",
  },
  "Big Country Toys": {
    storeName: "Big Country Toys",
    division: "4",
    subsidiary: "3",
    currency: "1",
  }
};

const storeConfig = storeConfigs[storeName];

if (!storeConfig) {
  throw new Error(`Unknown store: "${storeName}". Supported stores: ${Object.keys(storeConfigs).join(", ")}`);
}


const { lastIssuedAt, lastPayoutId } = input.memory

// Build Shopify payout search query string for the GraphQL query argument.
// status:PAID is always included. When a checkpoint exists, issued_at:>= is added
// so the server-side filter handles the checkpoint window.
const queryParts = ["status:paid"];

if (lastIssuedAt) {
  // Use >= so a payout sharing the checkpoint timestamp is not lost.
  // Step 3 applies only the ID tie-breaker for equal timestamps.
  queryParts.push(`issued_at:>=${lastIssuedAt}`);
}

// Cutoff date: only include payouts issued after May 1, 2025
queryParts.push("issued_at:>=2026-06-01");

const shopifyPayoutSearchQuery = queryParts.join(" ");

return [{
  storeConfig,
  checkpoint: { lastIssuedAt, lastPayoutId },
  shopifyPayoutSearchQuery,
  emailsRecipients
}];

// Extract Payouts from Shopify Response
// Step 2 handles server-side filtering (status:PAID + checkpoint window via issued_at:>=).
// This step only extracts, flattens, validates, and applies the equal-timestamp ID tie-breaker.

const shopifyRaw = input["shopifyGraphqlBetaYYYC"] || [];
const storeConfigStep = input["mapRPVQ"] || [];
const storeConfig = (storeConfigStep[0] || {}).storeConfig || {};
const checkpoint = (storeConfigStep[0] || {}).checkpoint || {};

const graphqlResult = shopifyRaw[0] || {};
const payoutConnection = graphqlResult?.shopifyPaymentsAccount?.payouts || {};
const edges = payoutConnection.edges || [];
const pageInfo = payoutConnection.pageInfo || {};

const allReturnedPayouts = edges.map(edge => edge.node).filter(Boolean);

const lastIssuedAt = checkpoint.lastIssuedAt || null;
const lastPayoutId = checkpoint.lastPayoutId || null;

const eligiblePayouts = allReturnedPayouts.filter(p => {
  // Defensive validation: Step 2 should only return PAID payouts.
  // If Shopify returns a non-PAID payout, the server-side filter is broken.
  if (p.status !== "PAID") {
    throw new Error(`Shopify GraphQL returned non-PAID payout ${p.id} with status ${p.status}; Step 2 query filter is not working`);
  }

  // Step 2 handles the checkpoint window with issued_at:>=lastIssuedAt.
  // This tie-breaker only prevents reprocessing the exact checkpoint payout
  // when issuedAt equals the checkpoint timestamp.
  if (lastIssuedAt && lastPayoutId && p.issuedAt === lastIssuedAt && p.id.split("/").pop() <= lastPayoutId) {
    return false;
  }

  return true;
});

const flattenedPayouts = eligiblePayouts.map(p => {
  const summary = p.summary || {};
  const flatSummary = {};

  for (const [key, val] of Object.entries(summary)) {
    flatSummary[key] = val?.amount !== undefined ? val.amount : val;
  }

  return {
    id: p.id.split("/").pop(),
    issuedAt: p.issuedAt,
    status: p.status,
    transactionType: p.transactionType || null,
    netAmount: p.net?.amount || "0",
    currencyCode: p.net?.currencyCode || null,
    summary: flatSummary,
    storeConfig
  };
});

return [{
  totalFetched: allReturnedPayouts.length,
  totalPaid: allReturnedPayouts.length,
  totalEligible: flattenedPayouts.length,
  hasNextPage: pageInfo.hasNextPage || false,
  endCursor: pageInfo.endCursor || null,
  payouts: flattenedPayouts
}];

