// Log: Skipped (Already Processed)
// This payout already has a Journal Entry in NetSuite — skip creation.
// Reads existingJournalEntry from Step 6 SuiteScript search output.

const payout = input["iterateJVCA"];
const idempotency = input["mapE3SM"] || {};
const nsSearch = input["netsuiteExecuteCustomCodeSU2D"] || {};
const existingJe = nsSearch.existingJournalEntry || (nsSearch.items || [])[0] || null;
const storeConfigStep = input["mapRPVQ"] || [];
const storeConfig = (storeConfigStep[0] || {}).storeConfig || {};

return [{
  store: storeConfig.storeName || "unknown",
  payoutId: payout?.id || idempotency.payoutId || nsSearch.payoutId || "unknown",
  externalId: idempotency.externalId || nsSearch.externalId || "unknown",
  issuedAt: payout?.issuedAt || null,
  issuedDate: payout?.issuedAt ? String(payout.issuedAt).split("T")[0] : null,
  status: payout?.status || null,
  transactionType: payout?.transactionType || payout?.type || null,
  currencyCode: payout?.currencyCode || payout?.net?.currencyCode || null,
  netAmount: Number(payout?.netAmount || payout?.net?.amount || 0),
  feeTotal: null,
  clearingAmount: null,
  journalEntryId: existingJe?.internalId || null,
  resultStatus: "skipped_already_processed",
  errorStep: null,
  errorMessage: null
}];

// Normalize Shopify Payout
// Validates required fields and normalizes the payout structure for downstream steps.
// IMPORTANT: Does NOT use legacyResourceId.

const payout = input["iterateJVCA"][0];
const storeConfigStep = input["mapRPVQ"] || [];
const storeConfig = (storeConfigStep[0] || {}).storeConfig || {};

if (!payout?.id) {
  throw new Error("Missing Shopify payout id");
}

if (!payout?.issuedAt) {
  throw new Error(`Missing issuedAt for payout ${payout.id}`);
}

const issuedDate = String(payout.issuedAt).split("T")[0];
const netAmountRaw = payout.net?.amount ?? payout.netAmount;

if (netAmountRaw === undefined || netAmountRaw === null || netAmountRaw === "") {
  throw new Error(`Missing net amount for payout ${payout.id}`);
}

return [{
  payoutId: payout.id,
  externalId: `shopify_payout_${payout.id}`,
  issuedAt: payout.issuedAt,
  issuedDate,
  memo: `Shopify payout reconciliation ${issuedDate} (${storeConfig.storeName})`,
  status: payout.status || null,
  transactionType: payout.transactionType || payout.type || null,
  currencyCode: payout.currencyCode || payout.net?.currencyCode || null,
  netAmount: Number(netAmountRaw),
  summary: payout.summary || {},
  storeConfig
}];

// Calculate Accounting Values
// Computes fee totals, clearing amount, and journal entry lines.
// Rules:
//   - Include all summary fields ending in "Fee" or "Fees"
//   - Include advanceFees
//   - Exclude refundsFeeGross
//   - Convert signed amounts into debit/credit sides
//   - Never send negative debit or credit values
//   - Omit zero-amount lines
//   - Block JE creation if debits ≠ credits after rounding

const data = (input["mapPV2R"] || [])[0] || {};
const summary = data.summary || {};

const roundMoney = (n) => Math.round(Number(n || 0) * 100) / 100;

// Sum all fee fields: keys ending in "Fee" or "Fees" (except refundsFeeGross), plus advanceFees
const feeTotal = Math.abs(Object.entries(summary)
  .filter(([key]) => {
    if (key === "refundsFeeGross") return false;
    if (key.endsWith("Fee") || key.endsWith("Fees")) return true;
    if (key === "advanceFees") return true;
    return false;
  })
  .reduce((sum, [, value]) => {
    return sum + Number(value?.amount !== undefined ? value.amount : (value ?? 0));
  }, 0));

const netAmount = Number(data.netAmount || 0);
const clearingSignedAmount = -(netAmount + feeTotal);

function toJournalLine(account, signedAmount, memo, extra) {
  const amount = roundMoney(Math.abs(Number(signedAmount || 0)));
  if (amount === 0) return null;

  if (signedAmount >= 0) {
    return { account, debit: amount, memo, ...(extra || {}) };
  }
  return { account, credit: amount, memo, ...(extra || {}) };
}

const lines = [
  toJournalLine("1113", netAmount, data.memo, { division: data.storeConfig?.division}),
  toJournalLine("471", feeTotal, data.memo, { department: "11", division: data.storeConfig?.division }),
  toJournalLine("1114", clearingSignedAmount, data.memo, { division: data.storeConfig?.division})
].filter(Boolean);

const totalDebits = roundMoney(lines.reduce((sum, line) => sum + Number(line.debit || 0), 0));
const totalCredits = roundMoney(lines.reduce((sum, line) => sum + Number(line.credit || 0), 0));
const isBalanced = totalDebits === totalCredits;

if (!isBalanced) {
  throw new Error(
    `Unbalanced journal entry for payout ${data.payoutId}: debits ${totalDebits}, credits ${totalCredits}`
  );
}

return [{
  ...data,
  feeTotal: roundMoney(feeTotal),
  clearingAmount: roundMoney(Math.abs(clearingSignedAmount)),
  clearingSignedAmount: roundMoney(clearingSignedAmount),
  lines,
  totalDebits,
  totalCredits,
  isBalanced
}];

// Build NetSuite Journal Entry Payload
// Constructs the JE record structure for the NetSuite SuiteScript Execute Custom Code step.
// Header: externalId, subsidiary, currency, division, tranDate, memo
// Lines: 1095 (East West Receivables), 8616 (Credit Card Fees, dept 810), 1099 (Shopify Clearing)
//
// NOTE on approvalStatus:
//   Not fully aligned with client yet. If storeConfig.approvalStatus is set, it will be included.
//   Otherwise omitted. The SuiteScript step should handle this gracefully.

const data = (input["mapVTMX"] || [])[0] || {};

if (!data.isBalanced) {
  throw new Error(`Unbalanced journal entry for payout ${data.payoutId}`);
}

// Build line items in NetSuite JournalEntry sublist format
const nsLines = data.lines.map((line, idx) => {
  const nsLine = {
    account: { id: line.account },
    memo: line.memo
  };

  if (line.debit !== undefined && line.debit > 0) {
    nsLine.debit = line.debit;
  }
  if (line.credit !== undefined && line.credit > 0) {
    nsLine.credit = line.credit;
  }
  if (line.department) {
    nsLine.department = { id: line.department };
  }
  if (line.division) {
    nsLine.division = { id: line.division };
  }

  return nsLine;
});

const payload = {
  externalId: data.externalId,
  subsidiary: { id: "3" },
  currency: { id: "1" },
  tranDate: data.issuedDate,
  memo: data.memo,
  line: nsLines
};

// Approval status — only include if defined in store config
if (data.storeConfig && data.storeConfig.approvalStatus) {
  payload.approvalStatus = data.storeConfig.approvalStatus;
}

return [{
  payoutId: data.payoutId,
  externalId: data.externalId,
  issuedAt: data.issuedAt,
  issuedDate: data.issuedDate,
  memo: data.memo,
  status: data.status,
  transactionType: data.transactionType,
  currencyCode: data.currencyCode,
  netAmount: data.netAmount,
  feeTotal: data.feeTotal,
  clearingAmount: data.clearingAmount,
  totalDebits: data.totalDebits,
  totalCredits: data.totalCredits,
  storeConfig: data.storeConfig,
  payload
}];

// Build Batch Summary
// Aggregates all payout log results from workflow memory.

const MEMORY_KEY = "shopifyPayoutReconciliationLogs";

function readMemoryArray(key) {
  const raw = input.memory?.[key];

  if (!raw) return [];
  if (Array.isArray(raw)) return raw;

  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
}

const extractionStep = (input["mapBEND"] || [])[0] || {};
const logResults = readMemoryArray(MEMORY_KEY);

const totalFetched =
  extractionStep.totalFetched !== undefined
    ? extractionStep.totalFetched
    : (extractionStep.payouts || []).length || logResults.length;

const totalEligible =
  extractionStep.totalEligible !== undefined
    ? extractionStep.totalEligible
    : (extractionStep.payouts || []).length || logResults.length;

let createdCount = 0;
let skippedCount = 0;
let failedCount = 0;
const failedPayouts = [];

for (const log of logResults) {
  if (log.resultStatus === "created") {
    createdCount++;
  } else if (log.resultStatus === "skipped_already_processed") {
    skippedCount++;
  } else if (log.resultStatus === "failed") {
    failedCount++;
    failedPayouts.push({
      payoutId: log.payoutId,
      externalId: log.externalId,
      errorStep: log.errorStep,
      errorMessage: log.errorMessage
    });
  } else {
    failedCount++;
    failedPayouts.push({
      payoutId: log.payoutId,
      externalId: log.externalId,
      errorStep: log.errorStep || "Unknown",
      errorMessage: log.errorMessage || "Unknown result status: " + log.resultStatus
    });
  }
}

const runTimestamp = new Date().toISOString();

const summary = {
  runTimestamp,
  totalPayoutsFetched: totalFetched,
  totalEligiblePayouts: totalEligible,
  createdCount,
  skippedCount,
  failedCount,
  failedPayouts,
  hasFailures: failedCount > 0,
  summaryMessage: [
    `Shopify Payout Reconciliation Summary (${runTimestamp})`,
    `Total payouts fetched: ${totalFetched}`,
    `Total eligible payouts: ${totalEligible}`,
    `Created: ${createdCount}`,
    `Skipped (already processed): ${skippedCount}`,
    `Failed: ${failedCount}`,
    failedPayouts.length > 0
      ? `\nFailed payout details:\n` + failedPayouts.map(f =>
          `  - Payout ${f.payoutId} (${f.externalId}): [${f.errorStep}] ${f.errorMessage}`
        ).join("\n")
      : ""
  ].filter(Boolean).join("\n")
};

return [summary];

// Update Checkpoint
// Determines the latest payout processed to persist as the checkpoint
// for the next run. Uses payout id as tie-breaker when multiple payouts
// share the same issuedAt date.

const logResults = input["mapGFNH"] || [];
const eligiblePayouts = input["mapBEND"] || [];

// Only update checkpoint if we processed at least one payout successfully
const processedLogs = logResults.filter(
  log => log.resultStatus === "created" || log.resultStatus === "skipped_already_processed"
);

if (processedLogs.length === 0) {
  // No successful processing, do not advance checkpoint
  return [{
    checkpointUpdated: false,
    reason: "No payouts were successfully processed in this run",
    lastIssuedAt: null,
    lastPayoutId: null
  }];
}

// Find the latest payout by issuedAt, using payoutId as tie-breaker
let latestLog = processedLogs[0];

for (const log of processedLogs) {
  const currentDate = log.issuedAt || "";
  const latestDate = latestLog.issuedAt || "";

  if (currentDate > latestDate) {
    latestLog = log;
  } else if (currentDate === latestDate) {
    // Tie-breaker: use payout id (string comparison of GIDs)
    const currentId = String(log.payoutId || "");
    const latestId = String(latestLog.payoutId || "");
    if (currentId > latestId) {
      latestLog = log;
    }
  }
}

return [{
  checkpointUpdated: true,
  lastIssuedAt: latestLog.issuedAt,
  lastPayoutId: latestLog.payoutId,
  totalProcessed: processedLogs.length,
  timestamp: new Date().toISOString()
}];
